import { Context, createContext } from 'react';

export type AccordionSectionContextProps = {
  triggerIsStart: boolean;
  triggerId: string;
  contentId: string;
  isExpanded: boolean;
  keepMounted: boolean;
  size: 'default' | 'condensed';
};

export const AccordionSectionContext: Context<AccordionSectionContextProps> =
  createContext<AccordionSectionContextProps>({
    triggerIsStart: false,
    triggerId: '',
    contentId: '',
    isExpanded: false,
    keepMounted: false,
    size: 'default',
  });
